  _row        record;
  _tree       jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'casement' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''casement'' — the casement profile must exist first';
  END IF;

  SELECT code INTO _product FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'casement' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _product IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''Casement'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  -- The trees below were generated with bottomHeight 83 and
  -- defaultFanlightBottomHeight 62. If the live profile disagrees, the
  -- templates would be built on one set of rails and every NEW opening a
  -- surveyor adds on another, so say so rather than write them.
  SELECT v.default_value INTO _ordinary
  FROM   public.default_profile_values v
  WHERE  v.profile_id = _profile_id AND v.field_key = 'casementSashPart.bottomHeight';
  SELECT v.default_value INTO _fanlight
  FROM   public.default_profile_values v
  WHERE  v.profile_id = _profile_id
    AND  v.field_key = 'casementSashPart.defaultFanlightBottomHeight';
  IF _ordinary IS DISTINCT FROM '83' OR _fanlight IS DISTINCT FROM '62' THEN
    RAISE EXCEPTION 'Casement bottom rails are % ordinary / % fanlight, expected 83 / 62 — run sql/step-as0 first (Step BI section 0b)',
      coalesce(_ordinary, 'missing'), coalesce(_fanlight, 'missing');
  END IF;

  IF jsonb_array_length(_templates) <> 4 THEN
    RAISE EXCEPTION 'Expected 4 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates)
      AS x(name text, sort_order int, group_name text, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_product), true);

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      -- Updated in place, so re-running never duplicates a template.
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id,
          sort_order = _row.sort_order, group_name = _row.group_name,
          updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step BI-1: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'casement', _row.group_name, 'Casement',
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step BI-1: % created', _row.name;
    END IF;
  END LOOP;
END $$;

COMMIT;


-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 2 — checks
-- ═══════════════════════════════════════════════════════════════════════════

-- 1. The seven Configurations and the two French casements, in order, each
--    with its profile, Product and Quantity set. Expect 45 / 50 / 60 / 70,
--    then the four new ones at 72 / 74 / 76 / 78, then 80 / 90.
SELECT t.name, t.group_name, t.window_type, t.sort_order, t.is_active,
       p.code AS profile_code,
       t.tree #>> '{values,product}'  AS product_code,
       t.tree #>> '{values,quantity}' AS quantity
FROM   public.drawing_templates t
LEFT   JOIN public.default_profiles p ON p.id = t.default_profile_id
WHERE  t.group_name = 'Combination Flush Casements'
ORDER  BY t.sort_order;

-- 2. What each new tree holds — one cill on each, and one glass per sash.
--    Expect, in sort order:
--      72  sashes 3, glass 3, mullions 2, transoms 0, cills 1
--      74  sashes 4, glass 4, mullions 3, transoms 0, cills 1
--      76  sashes 4, glass 4, mullions 2, transoms 1, cills 1
--      78  sashes 6, glass 6, mullions 2, transoms 1, cills 1
SELECT name, sort_order,
       (SELECT count(*) FROM jsonb_path_query(tree, 'strict $.**.part_type ? (@ == "casementSashPart")')) AS sashes,
       (SELECT count(*) FROM jsonb_path_query(tree, 'strict $.**.part_type ? (@ == "glassPart")'))        AS glass,
       (SELECT count(*) FROM jsonb_path_query(tree, 'strict $.**.part_type ? (@ == "mullionPart")'))      AS mullions,
       (SELECT count(*) FROM jsonb_path_query(tree, 'strict $.**.part_type ? (@ == "transomPart")'))      AS transoms,
       (SELECT count(*) FROM jsonb_path_query(tree, 'strict $.**.part_type ? (@ == "cillPart")'))         AS cills
FROM   public.drawing_templates
WHERE  sort_order IN (72, 74, 76, 78)
ORDER  BY sort_order;

-- 3. The frame sizes and the divider offsets. Expect 1299x1307 / 1699x1307 /
--    1499x1199 / 1499x1199; mullion offsets [393, 805] / [389, 799, 1209] /
--    [459, 937] / [459, 937]; transom offset none / none / 356 / 356; every
--    divider 27 thick.
SELECT name, sort_order,
       tree #>> '{children,3,values,width}'  AS frame_width,
       tree #>> '{children,3,values,height}' AS frame_height,
       (SELECT jsonb_agg(v ORDER BY v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.mullionStopSize != null).offset') v)  AS mullion_offsets,
       (SELECT jsonb_agg(v ORDER BY v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.transomStopSize != null).offset') v)  AS transom_offsets,
       (SELECT jsonb_agg(DISTINCT v) FROM jsonb_path_query(tree, 'strict $.**.values.thicknessInFrame') v)                        AS divider_thickness
FROM   public.drawing_templates
WHERE  sort_order IN (72, 74, 76, 78)
ORDER  BY sort_order;

-- 4. THE BOTTOM RAILS, which are the one thing that differs from Integrate's
--    own templates. Expect, in sort order:
--      72  [83, 83, 83]
--      74  [83, 83, 83, 83]
--      76  [83, 62, 83, 83]      -- the middle light alone is 62
--      78  [62, 62, 62, 83, 83, 83]
SELECT name, sort_order,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.casementTypeId != null).bottomHeight') v) AS bottom_rails,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.casementTypeId != null).operation') v)    AS operations
FROM   public.drawing_templates
WHERE  sort_order IN (72, 74, 76, 78)
ORDER  BY sort_order;

-- 5. CONFIGURATION 6'S SHORT TRANSOM. Expect ONE row whose startDivider and
--    endDivider are both NON-'0' and both equal to a mullion key in the same
--    tree — and for 72 / 74 / 78, every divider '0' / '0'.
SELECT name, sort_order,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.transomStopSize != null).startDivider') v) AS transom_start,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.transomStopSize != null).endDivider') v)   AS transom_end,
       (SELECT jsonb_agg(DISTINCT v) FROM jsonb_path_query(tree, 'strict $.**.values ? (@.mullionStopSize != null).startDivider') v) AS mullion_start
FROM   public.drawing_templates
WHERE  sort_order IN (72, 74, 76, 78)
ORDER  BY sort_order;

-- 6. NO stored surround list and NO stored ironmongery list on any of the
--    four. Expect NULL in both columns on every row.
SELECT name, sort_order,
       tree #> '{values,surroundLines}' AS stored_surround,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, 'strict $.**.values.ironmongeryLines') v) AS stored_ironmongery,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, 'strict $.**.values.isCasementMpls') v)   AS casement_mpls
FROM   public.drawing_templates
WHERE  sort_order IN (72, 74, 76, 78)
ORDER  BY sort_order;

-- 7. And on a NEW drawing made from each, priced on the live rules, the
--    figures to expect are in docs/reports/step-bi.md, group by group. In
--    short, offline on the captured snapshot:
